import java.io.IOException;
import java.util.Scanner;

public class NekoAndAkiPrank {
    private final static long MOD = 1_000_000_007;

    public void solve() throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] prev = new long[n + 1];
        long[] cur = new long[n + 1];
        long tWays = 0;
        prev[0] = 1;
        for (int i = 1; i < 2 * n; i++) {
            cur[0] = prev[1];
            cur[n] = prev[n - 1];
            for (int k = 1; k < n; k++) {
                cur[k] = (prev[k - 1] + prev[k + 1]) % MOD;
            }
            if (i % 2 == 1) {
                int limit = Math.min(i, 2 * n - i);
                for (int k = 0; k <= limit; k++) {
                    tWays = (tWays + cur[k]) % MOD;
                }
            }
            long[] temp = prev;
            prev = cur;
            cur = temp;
        }
        System.out.println(tWays);
    }

    public static void main(String[] args) throws IOException {
        NekoAndAkiPrank solution = new NekoAndAkiPrank();
        solution.solve();
    }
}
